"""RoboPaint trajectory driver. All motion uses the public robot client.
Image analysis is exclusively of the supplied exemplar and camera observations.
"""
import os,sys,json,time
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT='/app/output'
class Painter:
 def __init__(self):
  self.r=Robot();self.o=self.r.get_obs(cameras=[]);self.p=np.array(self.o.meta['proprio']['now'][7:14]);self.q=np.array([-3.98743083e-7,1.,-3.55532393e-7,-2.86572686e-8]);self.seq=int(open(OUT+'/seq').read()) if os.path.exists(OUT+'/seq') else 0
 def send(self,rows,cameras=[],fps=5):
  rows=np.asarray(rows);res=None
  for a in [rows[i:i+180] for i in range(0,len(rows),180)]:
   self.seq+=1;np.save(f'{OUT}/action_{self.seq:04d}.npy',a);open(OUT+'/seq','w').write(str(self.seq))
   before=self.r.status()
   try:res=self.r.submit('ee_pose',a,dt=.05,cameras=cameras,video='frames' if cameras else 'none',video_fps=fps)
   except Exception:
    status=self.r.wait_ready();print('RECOVERY',before,status,flush=True);raise
   res.save(f'{OUT}/run_{self.seq:04d}');self.p=np.array(res.meta['proprio']['now'][7:14]);print('run',self.seq,'steps',res.meta.get('control_steps'),'tip',self.p[:3], 'plan',res.meta.get('plan'),flush=True)
   if res.stopped:raise RuntimeError('Partial call')
  return res
 def move(self,xyz,speed=.06,hold=.3):
  end=np.r_[xyz,self.q];n=max(1,int(np.ceil(np.linalg.norm(end[:3]-self.p[:3])/speed/.05)));rows=np.linspace(self.p,end,n+1)[1:];rows=np.r_[rows,np.tile(end,(int(hold/.05),1))];return self.send(rows)
 def obs(self,name,cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=False):
  o=self.r.get_obs(cameras=cameras,depth=depth);o.save(OUT+'/'+name)
  for k,v in o.last.items():Image.fromarray(v).save(f'{OUT}/{name}_{k}.png')
  return o
if __name__=='__main__':
 p=Painter()
 if sys.argv[1]=='park':p.move([-.30,0,.13]);p.obs('park',depth=True)
PY
PYTHONPATH=/opt/tools python /app/output/gen.py park

